/**
 * Editor icon set — Alltra "Hugeicons" solid-rounded glyphs, ported from the Alltra
 * desktop app's @alltra/ui icon system (@hugeicons-pro/core-solid-rounded v4.2.3) so the
 * journal editor's toolbar, "/" menu, Pinned grid and block menu render the SAME filled
 * icons as the Alltra editor (replacing the earlier lucide outline set). Each glyph is a
 * filled 24×24 path drawn with fill=currentColor, so it tints from the surrounding text
 * color exactly like the desktop.
 *
 * Provenance (journal export → @hugeicons-pro/core-solid-rounded source glyph). Actions that
 * exist in the desktop editor panel use the SAME glyph it does; the rest are best-fit picks
 * for journal-only actions (marked ✧):
 *   BoldIcon=TextBoldIcon · ItalicIcon=TextItalicIcon · UnderlineIcon=TextUnderlineIcon
 *   StrikeIcon=TextStrikethroughIcon · TextIcon=TextIcon · Heading1Icon=Heading01Icon
 *   Heading2Icon=Heading02Icon · Heading3Icon=Heading03Icon ✧ · QuoteIcon=QuoteDownIcon
 *   CalloutIcon=BulbIcon · CodeIcon=SourceCodeIcon ✧ · DividerIcon=MinusSignIcon
 *   BulletedIcon=LeftToRightListBulletIcon · NumberedIcon=LeftToRightListNumberIcon
 *   ChecklistIcon=CheckmarkCircle02Icon · TodoIcon=CheckListIcon ✧ · ToggleIcon=ToggleOnIcon
 *   TableColumnsIcon=LayoutThreeColumnIcon ✧ · TableRowsIcon=LayoutThreeRowIcon ✧
 *   AlignCenterIcon=TextAlignCenterIcon · AlignLeftIcon=TextAlignLeftIcon
 *   AlignRightIcon=TextAlignRightIcon · ImageIcon=Image02Icon · LinkIcon=Link02Icon
 *   EmojiIcon=SmileIcon · DateIcon=Calendar04Icon · TagIcon=Tag02Icon
 *   BannerIcon=LayoutTopIcon ✧ · PageLinkIcon=FileLinkIcon ✧ · TradeLinkIcon=ChartCandlestickIcon ✧
 *   LineSpacingIcon=ParagraphSpacingIcon · LetterSpacingIcon=TextKerningIcon ✧
 *
 * Checklist vs To-do is a deliberate journal distinction (strike-through checklist vs plain
 * checkbox list) — two glyphs where the desktop panel has one Checklist tile.
 *
 * AUTO-GENERATED path data — regenerate by re-running the extract step against the Alltra
 * app's installed @hugeicons-pro/core-solid-rounded package (do not hand-edit the arrays).
 */
import { createElement } from "react";
import type { CSSProperties, SVGProps } from "react";

/** One SVG child: [tagName, attributes]. */
type Seg = [string, Record<string, string>];

/** Drop-in replacement for a lucide icon: `size` (px → width/height) + the usual
 *  className / style / svg props. Always renders filled with currentColor. */
export type EditorIcon = (
  props: { size?: number; className?: string; style?: CSSProperties } & Omit<SVGProps<SVGSVGElement>, "size">,
) => JSX.Element;

const make = (name: string, segs: Seg[]): EditorIcon => {
  const Comp: EditorIcon = ({ size = 24, className, style, ...rest }) =>
    createElement(
      "svg",
      { xmlns: "http://www.w3.org/2000/svg", viewBox: "0 0 24 24", width: size, height: size, fill: "none", className, style, ...rest },
      segs.map(([tag, attrs], i) => createElement(tag, { ...attrs, key: i })),
    );
  (Comp as { displayName?: string }).displayName = name;
  return Comp;
};

